import sys
import yaml

STATUS = {
    "INVALID_INPUT": "400", "UPLOAD_TOO_LARGE": "413", "UNSUPPORTED_IMAGE": "415",
    "FACE_QUALITY_REJECTED": "422", "AUTH_REQUIRED": "401", "SESSION_INVALID": "401",
    "RESOURCE_NOT_VISIBLE": "404", "CALLER_NOT_ALLOWED": "403", "FACE_NOT_VERIFIED": "403",
    "GRANT_REVOKED": "403", "IDEMPOTENCY_CONTENT_CONFLICT": "409", "BINDING_CHANGED": "409",
    "TASK_REPLACED": "409", "PHOTO_VERSION_CONFLICT": "409", "DEVICE_OCCUPIED": "409",
    "PLAN_NOT_READY": "409", "PLAN_COMPLETED": "409", "EXECUTION_NOT_RESUMABLE": "409",
    "RECORD_CONFLICT": "409", "CLOSURE_GAPS": "409", "STOP_NOT_CONFIRMED": "409",
    "BOUND_TO_OTHER": "409", "REQUEST_IN_PROGRESS": "409", "RATE_LIMITED": "429",
    "DEPENDENCY_UNAVAILABLE": "503", "DEPENDENCY_TIMEOUT": "504", "INTERNAL": "500",
    "UNSUPPORTED_CONTRACT": "422", "NOT_IMPLEMENTED": "501",
}

KNOWN = {"M3-A01": {"422"}, "M3-A02": {"422"}}
METHODS = ["get", "post", "put", "delete", "patch"]


def normalize(p):
    import re
    return re.sub(r"\{[^/]*\}", "{}", p)


def main(path):
    with open(path) as f:
        c = yaml.safe_load(f)
    orphans = []
    known_seen = set()
    total = 0
    foundation = 0
    declares500_no_gen = []
    for p, item in c.get("paths", {}).items():
        for m in METHODS:
            op = item.get(m)
            if not isinstance(op, dict):
                continue
            api = op.get("x-api-id")
            is_found = "x-foundation" in op
            if api is None and not is_found:
                continue
            total += 1
            if is_found:
                foundation += 1
            key = m.upper() + " " + normalize(p)
            xec = op.get("x-error-codes") or []
            supported = set()
            for code in xec:
                s = STATUS.get(code)
                if s:
                    supported.add(s)
            responses = op.get("responses") or {}
            if "500" in responses:
