            aid = api if api else "（x-foundation）"
            for code in responses:
                code = str(code)
                if len(code) == 3 and code[0] == "4" and code not in supported:
                    if code in KNOWN.get(aid, set()):
                        known_seen.add((aid, code))
                    else:
                        orphans.append((aid, key, code, sorted(supported)))
    print("total documented ops:", total, " x-foundation ops:", foundation)
    print("contract ops declaring 500:", len(declares500_no_gen))
    print("orphan 4xx (excluding known exception list):", len(orphans))
    for o in orphans:
        print("  ORPHAN", o)
    print("known-list entries seen as orphan:", sorted(known_seen))
    stale = [(a, s) for a, ss in KNOWN.items() for s in ss if (a, s) not in known_seen]
    print("known-list stale entries:", stale)


if __name__ == "__main__":
    main(sys.argv[1])

