#!/usr/bin/env python3
"""Discrimination evidence for the new orphan-4xx gate.

Derives ErrorCode -> defaultStatus DIRECTLY FROM ErrorCode.java (no hand-copied
dict), then replicates ApiDocsCoverageIT.orphan4xxResponseProblems() over the
authoritative contract. Proves the gate fires on the 9 known orphans and that
the M3-A01/M3-A02 422 exception entries are currently live (not stale).
"""
import re
import sys
import yaml

HTTP = {
    "BAD_REQUEST": "400", "PAYLOAD_TOO_LARGE": "413", "UNSUPPORTED_MEDIA_TYPE": "415",
    "UNPROCESSABLE_ENTITY": "422", "UNAUTHORIZED": "401", "NOT_FOUND": "404",
    "FORBIDDEN": "403", "CONFLICT": "409", "TOO_MANY_REQUESTS": "429",
    "SERVICE_UNAVAILABLE": "503", "GATEWAY_TIMEOUT": "504",
    "INTERNAL_SERVER_ERROR": "500", "NOT_IMPLEMENTED": "501",
}

KNOWN = {"M3-A01": {"422"}, "M3-A02": {"422"}}
METHODS = ["get", "post", "put", "delete", "patch"]


def normalize(p):
    return re.sub(r"\{[^/]*\}", "{}", p)


def parse_error_codes(path):
    src = open(path).read()
    out = {}
    for code, status in re.findall(r"^\s*([A-Z_]+)\(HttpStatus\.([A-Z_]+),", src, re.M):
        stat = HTTP.get(status)
        if stat is None:
            raise SystemExit("unknown HttpStatus constant: " + status)
        out[code] = stat
    return out


def main(contract_path, errorcode_path):
    status_of = parse_error_codes(errorcode_path)
    print("parsed ErrorCode enum members:", len(status_of))
    assert "INTERNAL" not in {}, "sanity"
    print("codes mapping to 500:", [c for c, s in status_of.items() if s == "500"])
    assert all(s != "500" for c, s in status_of.items() if c != "INTERNAL")

    c = yaml.safe_load(open(contract_path))
    orphans, known_seen, stale = [], set(), []
    total = 0
    for p, item in c.get("paths", {}).items():
        for m in METHODS:
            op = item.get(m)
            if not isinstance(op, dict):
                continue
            api = op.get("x-api-id")
            if api is None and "x-foundation" not in op:
                continue
            total += 1
            supported = {status_of[x] for x in (op.get("x-error-codes") or []) if x in status_of}
            aid = api if api else "（x-foundation）"
            for code in (op.get("responses") or {}):
                code = str(code)
                if len(code) == 3 and code[0] == "4" and code not in supported:
                    if code in KNOWN.get(aid, set()):
                        known_seen.add((aid, code))
                    else:
                        orphans.append((aid, m.upper(), normalize(p), code))
    for aid, ss in KNOWN.items():
        for s in ss:
            if (aid, s) not in known_seen:
                stale.append((aid, s))
    print("documented ops:", total)
    print("orphan 4xx (gate would report):", len(orphans))
    for o in orphans:
        print("  ORPHAN", o)
    print("exception-list entries currently matched (not stale):", sorted(known_seen))
    print("stale exception entries:", stale)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])

