KNOWN={"M3-A01":{"422"},"M3-A02":{"422"}}
def norm(p): return re.sub(r'\{[^/]*\}','{}',p)
def gate(c):
    orphans=[]; matched=set()
    for p,item in c['paths'].items():
        for m in ['get','post','put','delete','patch']:
            op=item.get(m)
            if not isinstance(op,dict): continue
            api=op.get('x-api-id')
            if api is None and 'x-foundation' not in op: continue
            sup={status_of[x] for x in (op.get('x-error-codes') or []) if x in status_of}
            aid=api or '（x-foundation）'
            for code in (op.get('responses') or {}):
                code=str(code)
                if len(code)==3 and code[0]=='4' and code not in sup:
                    if code in KNOWN.get(aid,set()): matched.add((aid,code))
                    else: orphans.append((aid,m.upper(),norm(p),code))
    stale=[(a,s) for a,ss in KNOWN.items() for s in ss if (a,s) not in matched]
    return orphans,stale
